package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicDecimalAddSubTest {
 private static Question q(String id,String prompt){return new Question(id,prompt,"poison","999");}
 private static Checker.Result check(Question q,String answer){return new Checker().check(q,List.of(),Collections.singletonList(answer));}
 @Test public void PublicOriginalsPermitFourAndTwelvePlacesAndSignedResultsIndependentlyOfPrivateKeys(){
  for(String[] row:new String[][]{{"decimalAdd","1.2345 + 2","3.2345"},{"decimalAdd","999999999.999999999999 + 0.000000000001","1000000000"},{"decimalAdd","1 + 0.001 + 2.03 + 3.4","6.431"},{"decimalSub","1 − 2.0000","-1"},{"decimalSub","0.1 - 0.2 - 0.3","-0.4"},{"decimalSub","0.00 − 0.000","0"}}){Question q=q(row[0],row[1]);assertFalse(DecimalAddSub.read(q).isEmpty());assertEquals(0,new BigDecimal(row[2]).compareTo(DecimalAddSub.value(q)));assertTrue(check(q,row[2]).correct());assertTrue(CurriculumLimits.NONE.allows(q));q.answers=null;q.expression=null;assertTrue(check(q,row[2]).correct());}
  Question q=q("decimalAdd","00001.20 + 0.0300");assertEquals(List.of("00001.20","0.0300"),DecimalAddSub.read(q));assertTrue(check(q,"1.23000").correct());try{DecimalAddSub.read(q).set(0,"999");fail("Public originals mutable");}catch(UnsupportedOperationException expected){}Question format=q("decimalAdd","0.5 + 0.5");format.answerFormat="decimalValue";assertTrue(check(format,"1").correct());format.answerFormat="decimal";assertEquals(Checker.Status.INPUT_NEEDED,check(format,"1").status);assertTrue(check(format,"1.0").correct());assertTrue(check(q("decimalSub","0 − 0.5"),"−0.5").correct());
 }
 @Test public void ReadOnlyGuideKeepsExactLegacyEightAndElevenFourteenFrameMetadata(){
  for(String[] row:new String[][]{{"decimalAdd","1.20 + 0.3"},{"decimalSub","3.000 − 0.125"}}){Question q=q(row[0],row[1]);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;Question control=q(row[0],row[1]);DecimalArithmeticRelations.attach(control);StudyGuide g=DecimalAddSub.guide(q);assertEquals("decimal-arithmetic-relations-v1",g.teachingVersion);assertEquals(8,g.frames.size());for(int i=0;i<8;i++){StudyGuide.Frame expected=control.studyGuide.frames.get(i),actual=g.frames.get(i);assertEquals(expected.instruction,actual.instruction);assertEquals(expected.before,actual.before);assertEquals(expected.after,actual.after);assertEquals(expected.expected,actual.expected);assertEquals(expected.inputFormat,actual.inputFormat);}HelpPlan h=HelpPlan.forQuestion(q);assertEquals(8,h.size());assertFalse(h.canTransfer());assertSame(stored,q.studyGuide);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);}
  for(List<String> operands:List.of(List.of("1.2","0.03","2"),List.of("25","6.27","0.8","4.125"))){Question q=DecimalAddSub.make("decimalAdd",operands);StudyGuide factory=q.studyGuide;List<String> expected=factory.frames.stream().map(f->f.expected).toList();StudyGuide guide=DecimalAddSub.guide(q);assertEquals(3*operands.size()+2,guide.frames.size());assertEquals("decimal-add-sub-v1",guide.teachingVersion);assertEquals(expected,guide.frames.stream().map(f->f.expected).toList());assertSame(factory,q.studyGuide);HelpPlan h=HelpPlan.forQuestion(q);HelpPlan.Draft draft=h.restore(null,q.id);assertEquals("decimal-add-sub-v1",draft.teachingVersion);draft.entries=new ArrayList<>(expected);draft.stage=expected.size();assertEquals(expected.size(),h.restore(draft.copy(),q.id).stage);assertEquals(0,DecimalAddSub.value(q).compareTo(new BigDecimal(h.enteredAnswer(draft))));assertFalse(h.canTransfer());}
 }
 @Test public void LongGeneralShiftedValuesAreReachableWithoutChangingExpectedFormatsOrSharedExpressionGuards(){
  Question q=q("decimalAdd","999999999.999999999999 + 0.000000000001 + 1");HelpPlan h=HelpPlan.forQuestion(q);StudyGuide g=DecimalAddSub.guide(q);assertEquals(11,h.size());List<String> entered=List.of("999999999.999999999999","0.000000000001","1","12","1000000000000","999999999999999999999","1","1000000000000","1000000000000000000000","1000000001000000000000","1000000001");for(int i=0;i<entered.size();i++)assertTrue("stage"+i,h.step(i).accepts(entered.get(i)));assertTrue(g.frames.get(5).expected.length()>30);assertEquals("999999999999999999999.000000000000",g.frames.get(5).expected);assertTrue(h.step(3).accepts("12/1"));assertTrue(h.step(5).accepts("999999999999999999999/1"));assertFalse(h.step(0).accepts("999999999999999999999/1000000000000"));assertFalse(h.step(5).accepts("1000000000000000000000"));assertTrue(DecimalAddSub.references(q,8,entered.subList(0,8)).containsValue("999999999999999999999"));
  try{Expression.number(g.frames.get(5).expected);fail("Shared30-character component guard widened");}catch(IllegalArgumentException expected){}try{Expression.number("0."+"1".repeat(13));fail("Shared12-place guard widened");}catch(IllegalArgumentException expected){}
 }
 @Test public void ReferencesOnlyDisplayCheckedLearnerDependenciesUsingFullExistingLabels(){
  Question q=q("decimalAdd","1.20 + 0.3");List<String> entered=List.of("1.200","0.30","2","100","0120","30","150");assertEquals(Map.of("옮긴 왼쪽 수 A = x × u = ","0120","옮긴 오른쪽 수 B = y × u = ","30"),DecimalAddSub.references(q,6,entered));assertEquals(Map.of("옮길 자릿수 p = ","2","자릿값 배수 u = p칸 이동에 맞는 배수 = ","100","정수 합 r = A + B = ","150"),DecimalAddSub.references(q,7,entered));assertEquals(Map.of(),DecimalAddSub.references(q,6,List.of("1.2","0.3","2","100","121","29")));assertEquals(Map.of(),DecimalAddSub.references(q,0,entered));assertEquals(Map.of(),DecimalAddSub.references(q,8,entered));
  Question multi=q("decimalSub","3 − 0.125 − 0.5 − 0.375");List<String> values=List.of("3","0.125","0.5","0.375","3","1000","3000","125","500","375","2875","2375","2000");assertEquals(Map.of("계산 1의 결과 = ","2875","옮긴 3번째 수 = ","500"),DecimalAddSub.references(multi,11,values));assertEquals(Map.of("옮길 자릿수 = ","3","자릿값 배수 = ","1000","계산 3의 결과 = ","2000"),DecimalAddSub.references(multi,13,values));assertEquals(Map.of(),DecimalAddSub.references(null,6,values));
 }
 @Test public void OptionalPartialAndFullWorkKeepPublicArithmeticAnchorsAndWorkErrorTargets(){
  Question q=q("decimalAdd","0.1 + 0.2");q.kind="complexRoots";q.calculationMethod="written";Checker c=new Checker();assertTrue(c.check(q,List.of("0.1+0.2=0.3"),List.of("0.3"),List.of(Checker.StepKind.FULL)).correct());assertTrue(c.checkSteps(q,List.of("0.1+0.2=0.3"),List.of(Checker.StepKind.FULL)).correct());Checker.Result wrong=c.check(q,List.of("999=999"),List.of("0.3"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.WRONG_STEP,wrong.status);assertEquals(Checker.InputTarget.WORK,wrong.inputTarget);assertEquals(0,wrong.index);Checker.Result zeroWithDot=c.check(q,List.of("0.1+0.2=0."),List.of("0.3"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.WRONG_STEP,zeroWithDot.status);assertEquals(Checker.InputTarget.WORK,zeroWithDot.inputTarget);assertEquals(1,zeroWithDot.part);Checker.Result incomplete=c.check(q,List.of("0.1+0.2="),List.of("0.3"),List.of(Checker.StepKind.FULL));assertEquals(Checker.Status.INPUT_NEEDED,incomplete.status);assertEquals(Checker.InputTarget.WORK,incomplete.inputTarget);assertTrue(c.check(q,List.of("2+3=5"),List.of("0.3"),List.of(Checker.StepKind.PARTIAL)).correct());assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);assertEquals("complexRoots",q.kind);q.stepSupport=false;assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of("0.1+0.2=0.3"),List.of("0.3"),List.of(Checker.StepKind.FULL)).status);assertTrue(c.check(q,List.of("2+3=5"),List.of("0.3"),List.of(Checker.StepKind.PARTIAL)).correct());
 }
 @Test public void MalformedSourcesAndLongOrUnsupportedAnswersReturnInputNeededWithoutPrivateFallback(){
  for(String prompt:List.of("1.2345678901234 + 2","1000000000 + 2","1 + 2 × 3","1 + 2 + 3 + 4 + 5","1 + poison","-1 + 2","1e2 + 2","1. + 2")){Question q=q("decimalAdd",prompt);q.studyGuide=new StudyGuide().step("private","private","","999");StudyGuide stored=q.studyGuide;assertTrue(DecimalAddSub.read(q).isEmpty());assertNull(DecimalAddSub.guide(q));assertNull(HelpPlan.forQuestion(q));assertNull(DecimalAddSub.value(q));assertNull(DecimalAddSub.workQuestion(q));assertSame(stored,q.studyGuide);assertEquals(Checker.Status.INPUT_NEEDED,check(q,"999").status);}
  Question q=q("decimalAdd","1 + 2");for(String answer:List.of("1".repeat(121),"1".repeat(241),"3/1","3e0","3+0","3,0"))assertEquals(answer,Checker.Status.INPUT_NEEDED,check(q,answer).status);assertEquals(Checker.Status.INPUT_NEEDED,check(q,null).status);assertEquals(List.of(),DecimalAddSub.read(null));assertNull(DecimalAddSub.guide(null));assertNull(DecimalAddSub.value(null));assertEquals(Map.of(),DecimalAddSub.references(q,2,null));
 }
}
